esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an arbitrary amount to forward to c.go to exercise payable behavior.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Read owner before the call via public getter
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Make the state-changing call on c, capturing whether it reverted.
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // The contract C's go uses a hardcoded external target address T.
        // This property asserts that owner cannot be changed to that target
        // address by calling go, for any input and regardless of revert.
        // We express that as: ownerAfter != T.
        address T = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

        // General rule: ownerAfter equals ownerBefore (owner cannot be set to T),
        // and specifically ownerAfter is never equal to T.
        assert(ownerAfter == ownerBefore && ownerAfter != T);
    }

    receive() external payable {}
}

